#pragma once

// Atmospheric absorption, ISO 9613-1:1993.
//
// Ported from panam's panam_acoustics/iso_9613_1_1993.py, which is in turn
// derived from python-acoustics (BSD-3-Clause).  The formulas are reproduced
// term for term so the two implementations can be checked against each other;
// tests/test_atmosphere.cpp pins the C++ to values generated by the Python.
//
// The database's own EAA is a single broadband dB/km factor, fitted for the
// spectrum the source happened to have.  This is the per-band alternative: a
// real absorption coefficient at each frequency, which is what lets a spectrum
// be propagated to the ground rather than a single overall level.
//
// Pressure is in kPa throughout, matching the standard and the Python; that is
// the one unit here that is easy to get wrong, since the rest of the code is SI.

#include <cstddef>
#include <vector>

namespace niceops {

// Reference conditions of the standard.
inline constexpr double reference_temperature = 293.15; // K
inline constexpr double reference_pressure = 101.325; // kPa
inline constexpr double triple_point_temperature = 273.16; // K

struct Atmosphere
{
    double temperature = reference_temperature; // K
    double pressure = reference_pressure; // kPa
    double relative_humidity = 20.0; // percent; panam's default

    // Speed of sound, m/s.  The standard's own expression, not sqrt(gamma R T):
    // they differ by a few tenths of a percent and this is the one the
    // absorption coefficients were fitted against.
    double sound_speed() const;

    // Saturation vapor pressure, kPa.
    double saturation_pressure() const;

    // Molar concentration of water vapor, percent.
    double molar_concentration_water_vapor() const;

    // Relaxation frequencies of oxygen and nitrogen, Hz.  Both depend only on
    // the atmosphere, so hoist them out of any per-frequency loop.
    double relaxation_frequency_oxygen() const;
    double relaxation_frequency_nitrogen() const;

    // Absorption coefficient at one frequency, dB/m.
    //
    // This recomputes both relaxation frequencies on every call, exactly as the
    // Python properties do.  It is the readable form, not the fast one: for a
    // set of bands use absorption_coefficients() below, which computes them
    // once.
    double attenuation_coefficient(double frequency) const;
};

// Absorption coefficients in dB/m for each band center, computed with the
// relaxation frequencies evaluated once.
//
// This is what the propagation path wants: the coefficients depend only on the
// atmosphere and the band centers, so a run computes them once and then pays a
// multiply per band per evaluation rather than a dozen exp() and pow() calls.
std::vector<double> absorption_coefficients(const Atmosphere& atmosphere,
        const std::vector<double>& frequencies);

} // namespace niceops
